54	    const int64_t n_embd_head = hparams.n_embd_head_v();
55	
56	    GGML_ASSERT(n_embd_head == hparams.n_embd_head_k());
57	    GGML_ASSERT(n_embd_head == n_rot);
58	
59	    ggml_tensor * cur;
60	    ggml_tensor * inpL;
61	
62	    inpL = build_inp_embd(model.tok_embd);
63	
64	    // inp_pos - contains the positions
65	    ggml_tensor * inp_pos = build_inp_pos();
66	
67	    auto * inp_attn = build_attn_inp_kv();
68	
69	    ggml_tensor * inp_out_ids = build_inp_out_ids();
70	
71	    for (int il = 0; il < n_layer; ++il) {
72	        res->t_layer_inp[il] = inpL;
73	
74	        ggml_tensor * inpSA = inpL;
75	
76	        // norm
77	        cur = build_norm(inpL,
78	                model.layers[il].attn_norm, NULL,
79	                LLM_NORM_RMS, il);
80	        cb(cur, "attn_norm", il);
81	
82	        // self-attention
83	        {
84	            // compute Q and K and RoPE them
85	            auto [Qcur, Kcur, Vcur] = build_qkv(model.layers[il], cur,
86	                    n_embd_head, n_head, n_head_kv, il);
87	
88	            Qcur = build_norm(Qcur, model.layers[il].attn_q_norm, NULL, LLM_NORM_RMS, il);
89	            cb(Qcur, "Qcur_normed", il);
90	
91	            Qcur = ggml_rope_ext(
92	                    ctx0, Qcur, inp_pos, nullptr,
93	                    n_rot, rope_type, n_ctx_orig, freq_base, freq_scale,
94	                    ext_factor, attn_factor, beta_fast, beta_slow
95	                    );
96	
97	            Kcur = build_norm(Kcur, model.layers[il].attn_k_norm, NULL, LLM_NORM_RMS, il);
98	            cb(Kcur, "Kcur_normed", il);
99	
100	            Kcur = ggml_rope_ext(
101	                    ctx0, Kcur, inp_pos, nullptr,
102	                    n_rot, rope_type, n_ctx_orig, freq_base, freq_scale,
103	                    ext_factor, attn_factor, beta_fast, beta_slow
104	                    );
105	
106	            cb(Qcur, "Qcur", il);
107	            cb(Kcur, "Kcur", il);
108	            cb(Vcur, "Vcur", il);
109	
110	            cur = build_attn(inp_attn,
111	                    model.layers[il].wo, model.layers[il].wo_b, model.layers[il].wo_s,
112	                    Qcur, Kcur, Vcur, nullptr, nullptr, nullptr, 1.0f/sqrtf(float(n_embd_head)), il);
113	        }
114	        if (il == n_layer - 1 && inp_out_ids) {
115	            cur   = ggml_get_rows(ctx0,   cur, inp_out_ids);
116	            inpSA = ggml_get_rows(ctx0, inpSA, inp_out_ids);
117	        }
118	        ggml_tensor * ffn_inp = ggml_add(ctx0, cur, inpSA);
119	        cb(ffn_inp, "ffn_inp", il);
120	
