123	                model.layers[il].ffn_norm, NULL,
124	                LLM_NORM_RMS, il);
125	        cb(cur, "ffn_norm", il);
126	
127	        cur = build_ffn(cur,
128	                model.layers[il].ffn_up,   NULL, model.layers[il].ffn_up_s,
129	                model.layers[il].ffn_gate, NULL, model.layers[il].ffn_gate_s,
130	                model.layers[il].ffn_down, NULL, model.layers[il].ffn_down_s,
131	                NULL,
